      "scope_checks": [
        {
          "sid": "s001",
          "source_scope": "推动；使向前移动（物理）",
          "relation": "语义等价",
          "reason": "核心组用 cause to move forward with force 对应源“推动”，保留物理推进方向，词性、对象与证据一致。",
          "evidence_ids": ["wn31:v:01514338"]
        },
        {
          "sid": "s002",
          "source_scope": "驱使；促使行动（汉语可含较强驱动，但所给证据为提供动机）",
          "relation": "语义等价",
          "reason": "扩展组“促使行动（提供动力或动机）”与 give an incentive for action 一致；注释澄清不等同于一切强迫，未额外扩大范围。",
          "evidence_ids": ["wn31:v:01653541"]
        }
      ],
      "confirmed_within_supplied_evidence": [],
      "unresolved": [
        "“驱使”在汉语中可能含有命令或强迫义，所供 WordNet 证据仅覆盖“提供动机”；若来源教学意图含强迫驱动，则扩展层需要补充词典证据或暂存该剩余范围。"
      ],
      "preferences": [
        "将物理“推动”置于核心、动机“驱使”置于扩展，属于教学排序差异，未影响覆盖。"
      ],
      "note": "独立审计认为两个源义均有对应证据覆盖；未确认范围收窄缺陷。强迫义待核不构成已证丢失。"
    },
    {
      "id": "SG25-503acf004b50",
      "scope_checks": [
        {
          "sid": "s001",
          "source_scope": "法规（汉语可泛指法律、行政法规、部门规章等）",
          "relation": "范围收窄",
          "reason": "候选限定为“立法机关制定的成文法”，由 act passed by a legislative body 支持；但汉语“法规”可能宽于英语 statute，因此按英语证据收窄，需来源核验。",
          "evidence_ids": ["wn31:n:06576378", "wn31:s:02294522"]
        },
        {
          "sid": "s002",
          "source_scope": "法令；立法机关制定之法",
          "relation": "语义等价",
          "reason": "候选“法令（限立法机关制定的成文法）”与 WordNet 立法行为定义一致。",
          "evidence_ids": ["wn31:n:06576378"]
        }
      ],
      "confirmed_within_supplied_evidence": [],
      "unresolved": [
        "源“法规”的汉语范围可能含行政法规、部门规章等非立法机关规范；所供英语词典将 statute 限定为立法机关成文法，需确认原文是否意图泛指法规还是已按英语 statute 收窄。"
      ],
      "preferences": [
        "将“法规/法令”合并在同一核心组的处理妥当，不改变每个源义的可追溯性。"
      ],
      "note": "候选通过英语立法机关成文法定义对宽泛的汉语“法规”作了必要限定；该源范围待核，不判为生成器覆盖错误。"
    }
  ]
}
